/**
 * Product photos generated by scripts/build-images.py from the cut-outs in
 * design/. `width` and `height` are the largest variant, used for the
 * aspect ratio (prevents layout shift).
 */

export interface ProductPhoto {
  /** Path without size and extension. */
  src: string
  width: number
  height: number
}

export const photoWidths = [640, 960, 1440]

/** PNG fallback width for browsers without AVIF/WebP. */
export const fallbackWidth = 960

export const photos = {
  /** Clássico: pão com gergelim, alface, maionese, picles, tomate, cheddar e carne. */
  classico: { src: '/images/burger-classico', width: 1440, height: 1134 },
  /** Duplo: duas carnes com cheddar derretido escorrendo. */
  duplo: { src: '/images/burger-duplo', width: 1440, height: 1278 },
  /** Torre: duas carnes, cheddar, cebolas, picles, tomate e alface, com ingredientes no ar. */
  torre: { src: '/images/burger-torre', width: 1440, height: 1490 },
} satisfies Record<string, ProductPhoto>

export const heroPhoto = photos.torre

export const heroImageSizes =
  '(min-width: 104em) 51rem, (min-width: 75em) 46vw, (min-width: 64em) 52vw, (min-width: 48em) 78vw, 100vw'

export const srcSet = (src: string, format: string) =>
  photoWidths.map((width) => `${src}-${width}.${format} ${width}w`).join(', ')
